/* @autogenerated */
package net.civeira.phylax.feature.observe.source.sync;

import jakarta.enterprise.context.ApplicationScoped;
import jakarta.enterprise.event.Observes;
import lombok.RequiredArgsConstructor;
import net.civeira.phylax.feature.access.oauthclient.domain.OauthClient;
import net.civeira.phylax.feature.access.oauthclient.domain.event.OauthClientCreateEvent;
import net.civeira.phylax.feature.access.oauthclient.domain.event.OauthClientDeleteEvent;
import net.civeira.phylax.feature.access.oauthclient.domain.event.OauthClientDisableEvent;
import net.civeira.phylax.feature.access.oauthclient.domain.event.OauthClientEnableEvent;
import net.civeira.phylax.feature.access.oauthclient.domain.event.OauthClientUpdateEvent;
import net.civeira.phylax.feature.observe.source.ObservedSourceSyncService;
import net.civeira.phylax.feature.observe.source.OriginRef;

/**
 * Keeps the observed-source of each oauth client in sync with its domain events.
 *
 * Generated by the trait observable from the model (entity oauth-client, key code, label code).
 */
@ApplicationScoped
@RequiredArgsConstructor
public class OauthClientObservedSourceSync {

  private final ObservedSourceSyncService sync;

  void onCreate(@Observes final OauthClientCreateEvent event) {
    sync.upsert(OauthClientObservedSourceSync.toOrigin(event.getPayload()));
  }

  void onUpdate(@Observes final OauthClientUpdateEvent event) {
    sync.upsert(OauthClientObservedSourceSync.toOrigin(event.getPayload()));
  }

  void onEnable(@Observes final OauthClientEnableEvent event) {
    sync.upsert(OauthClientObservedSourceSync.toOrigin(event.getPayload()));
  }

  void onDisable(@Observes final OauthClientDisableEvent event) {
    sync.upsert(OauthClientObservedSourceSync.toOrigin(event.getPayload()));
  }

  void onDelete(@Observes final OauthClientDeleteEvent event) {
    sync.detach("app", event.getPayload().getUid());
  }

  static OriginRef toOrigin(final OauthClient oauthClient) {
    return new OriginRef("app", oauthClient.getUid(), oauthClient.getCode(), oauthClient.getCode(),
        Boolean.TRUE.equals(oauthClient.isEnabled()));
  }
}
